solution.js:
let plaetze = 5;
const buchenKnopf = document.getElementById("buchen-knopf");
const anzeige = document.getElementById("anzeige");
buchenKnopf.addEventListener("click", function () {
  plaetze = plaetze - 1;
  anzeige.textContent = "Noch " + plaetze + " Plätze frei";
});

